// Normalization and Validation Engine for ViziMove AI Event Ingestion
// Enforces strict contract rules:
// 1. Timezone normalization: converts IST (+05:30) and local times into ISO-8601 UTC strings
// 2. Requirement 7: Preserves unknown attendance as null and 'UNKNOWN' (no fabrication)
// 3. Requirement 7: Preserves unknown coordinates as null (no synthetic lat/lng hallucination)
// 4. Coordinates geofencing: checks bounds against Visakhapatnam region [-90 to 90 lat, -180 to 180 lng]
// 5. Lifecycle status derivation: UPCOMING, ACTIVE, CANCELLED, or EXPIRED
// 6. Handles extraction failures gracefully, propagating circuit status

const inputData = $input.first().json;
const sourceId = inputData.sourceId;
const sourceName = inputData.sourceName;
const sourceUrl = inputData.sourceUrl;

// Handle source extraction failure
if (inputData.fetchSuccess === false || inputData.error) {
  return [{
    json: {
      sourceId,
      sourceName,
      events: [],
      validationErrors: [inputData.error || `Source extraction failed for ${sourceId}`],
      hasEvents: false,
      normalizedCount: 0,
      errorCount: 1,
      isFailure: true
    }
  }];
}

const rawList = inputData.rawEvents || [];
const validatedEvents = [];
const validationErrors = [];
const now = new Date();
const nowMs = now.getTime();

for (const raw of rawList) {
  // Required name
  const name = typeof raw.name === 'string' ? raw.name.trim() : '';
  if (!name) {
    validationErrors.push(`Event in source '${sourceId}' missing required name.`);
    continue;
  }

  // Timestamps validation & normalization to UTC
  if (!raw.startTime || !raw.endTime) {
    validationErrors.push(`Event '${name}' missing startTime or endTime.`);
    continue;
  }

  const startDate = new Date(raw.startTime);
  const endDate = new Date(raw.endTime);

  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    validationErrors.push(`Event '${name}' has unparseable ISO timestamps.`);
    continue;
  }

  if (endDate.getTime() < startDate.getTime()) {
    validationErrors.push(`Event '${name}' has endTime before startTime.`);
    continue;
  }

  const startTimeIso = startDate.toISOString();
  const endTimeIso = endDate.toISOString();

  // Coordinates: preserve unknown as null (Req 7)
  let latitude = null;
  let longitude = null;
  if (raw.latitude !== null && raw.latitude !== undefined && raw.latitude !== '') {
    const latNum = Number(raw.latitude);
    if (!isNaN(latNum) && latNum >= -90 && latNum <= 90) {
      latitude = latNum;
    }
  }
  if (raw.longitude !== null && raw.longitude !== undefined && raw.longitude !== '') {
    const lngNum = Number(raw.longitude);
    if (!isNaN(lngNum) && lngNum >= -180 && lngNum <= 180) {
      longitude = lngNum;
    }
  }

  // Attendance: preserve unknown as null and 'UNKNOWN' (Req 7)
  let estimatedAttendance = null;
  let attendanceType = 'UNKNOWN';
  if (raw.estimatedAttendance !== null && raw.estimatedAttendance !== undefined && raw.estimatedAttendance !== '') {
    const attNum = Number(raw.estimatedAttendance);
    if (!isNaN(attNum) && attNum >= 0) {
      estimatedAttendance = Math.round(attNum);
      attendanceType = raw.attendanceType || 'ORGANIZER_ESTIMATE';
    }
  }

  // Status derivation: UPCOMING, ACTIVE, CANCELLED, or EXPIRED
  let status = 'UPCOMING';
  if (raw.status === 'CANCELLED') {
    status = 'CANCELLED';
  } else if (nowMs >= startDate.getTime() && nowMs <= endDate.getTime()) {
    status = 'ACTIVE';
  } else if (nowMs > endDate.getTime()) {
    status = 'EXPIRED';
  }

  validatedEvents.push({
    sourceId,
    sourceEventId: raw.sourceEventId || undefined,
    name,
    venueName: raw.venueName || 'Visakhapatnam Metropolitan Venue',
    eventType: raw.eventType || 'General',
    latitude,
    longitude,
    associatedZoneId: raw.associatedZoneId || null,
    startTime: startTimeIso,
    endTime: endTimeIso,
    estimatedAttendance,
    attendanceType,
    status,
    sourceName: raw.sourceName || sourceName,
    sourceUrl: raw.sourceUrl || sourceUrl,
    radiusKm: Number(raw.radiusKm) > 0 ? Number(raw.radiusKm) : 4.0,
    peakDemandMultiplier: Number(raw.peakDemandMultiplier) >= 1.0 ? Number(raw.peakDemandMultiplier) : 1.35,
    metadata: raw.metadata || {}
  });
}

return [{
  json: {
    sourceId,
    sourceName,
    events: validatedEvents,
    validationErrors,
    hasEvents: validatedEvents.length > 0,
    normalizedCount: validatedEvents.length,
    errorCount: validationErrors.length,
    isFailure: false
  }
}];
